DROP TABLE lesson.t,lesson.hidden,lesson.generated;CREATE TABLE lesson.t (id INT PRIMARY KEY,n INT NULL,name VARCHAR(40),e ENUM('','界','O''Brien'),s SET('界','a'),vb VARBINARY(40),KEY px(name(3),n),KEY sn(n)) ENGINE=InnoDB ROW_FORMAT=DYNAMIC; INSERT INTO lesson.t VALUES (1,10,'界abc','界','界',X'00FF'),(2,NULL,'O''Brien','O''Brien','a',X'4142'); CREATE TABLE lesson.hidden (n INT,name VARCHAR(20),KEY n_idx(n)) ENGINE=InnoDB ROW_FORMAT=COMPACT; INSERT INTO lesson.hidden VALUES (1,'界'),(2,NULL); CREATE TABLE lesson.generated (id INT PRIMARY KEY,n INT,g INT GENERATED ALWAYS AS (n+1) STORED,v INT GENERATED ALWAYS AS (n+2) VIRTUAL,KEY g_idx(g)) ENGINE=InnoDB ROW_FORMAT=DYNAMIC; INSERT INTO lesson.generated (id,n) VALUES (1,10),(2,NULL);